func TestUpdaterUpdateTerraformFile(t *testing.T) {
	t.Parallel()

	dir, err := os.MkdirTemp("", "updater-terraform-")
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() {
		if err := os.RemoveAll(dir); err != nil {
			t.Errorf("remove temporary directory: %v", err)
		}
	})

	file := filepath.Join(dir, "versions.tf")
	if err := os.WriteFile(file, []byte("module \"x\" {\n  version = \"1.2.3\"\n}\n"), 0o644); err != nil {
		t.Fatal(err)
	}

	if err := NewUpdater().Update(file, "1.3.0"); err != nil {
		t.Fatalf("Update() error = %v", err)
	}

	got, err := os.ReadFile(file)
	if err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(string(got), `version = "1.3.0"`) {
		t.Fatalf("updated file = %s", got)
	}
}

func TestUpdaterDiff(t *testing.T) {
	t.Parallel()

	dir := t.TempDir()
	file1 := filepath.Join(dir, "versions.tf")
	file2 := filepath.Join(dir, "main.tf")
	original1 := "module \"x\" {\n  version = \"1.2.3\"\n}\n"
	original2 := "module \"y\" {\n  version = \"1.2.3\"\n}\n"
	if err := os.WriteFile(file1, []byte(original1), 0o644); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(file2, []byte(original2), 0o644); err != nil {
		t.Fatal(err)
	}

	diff, err := NewUpdater().Diff(file1+","+file2, "1.3.0")
	if err != nil {
		t.Fatalf("Diff() error = %v", err)
	}
	if !strings.Contains(diff, "--- a/"+file1+"\n+++ b/"+file1+"\n") {
		t.Fatalf("diff = %s", diff)
	}
	if !strings.Contains(diff, "--- a/"+file2+"\n+++ b/"+file2+"\n") {
		t.Fatalf("diff = %s", diff)
	}
	if !strings.Contains(diff, "-  version = \"1.2.3\"\n+  version = \"1.3.0\"\n") {
		t.Fatalf("diff = %s", diff)
	}
	got1, err := os.ReadFile(file1)
	if err != nil {
		t.Fatal(err)
	}
	if string(got1) != original1 {
		t.Fatalf("Diff() modified file1: %s", got1)
	}
}

